import json

# Read the full JSON file and search every field for anything that might be Jan 2003 bond yield
with open('/app/resources/treasury_bulletin_2003_03.json', 'r') as f:
    data = json.load(f)

def search_for_yield(obj, path=""):
    """Recursively search for yield-like numbers"""
    results = []

    if isinstance(obj, dict):
        for key, value in obj.items():
            results.extend(search_for_yield(value, f"{path}.{key}"))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(search_for_yield(item, f"{path}[{i}]"))
    elif isinstance(obj, str):
        # Look for patterns like "Jan 2003 5.xx" or similar
        if '2003' in obj:
            # Check if the string also contains a yield-like number
            import re
            matches = re.findall(r'2003.*?(\d+\.\d+)', obj)
            for m in matches:
                if 5.0 <= float(m) <= 8.0:
                    results.append((path, obj[:200], m))
    return results

results = search_for_yield(data)
if results:
    for r in results:
        print(f"Path: {r[0]}")
        print(f"Context: {r[1]}")
        print(f"Value: {r[2]}")
        print("---")
else:
    print("No yield data found for 2003")

# Let me also check for any other numeric table data
print("\nNow checking for any numeric tables...")
for key in ['elements', 'pages']:
    if key in data['document']:
        print(f"Found {key}")
